import { mkdirSync } from "node:fs";
import { dirname } from "node:path";
import { chromium, type Browser, type Page, type Request } from "playwright";
import { CRITICAL_ERROR_PHRASE, normalizeHealth, type HealthSnapshot } from "./health.ts";
import type { Page as SitePage, Site } from "./sites.ts";

export const VIEWPORTS = {
  desktop: { width: 1440, height: 900 },
  mobile: { width: 390, height: 844 },
} as const;
export type ViewportName = keyof typeof VIEWPORTS;

/** Milliseconds. navigation covers load; the others each have their own cap after it. */
export const TIMEOUTS = { navigation: 30_000, networkIdle: 15_000, lazyScroll: 15_000, settle: 5_000, screenshot: 30_000 };
export type Timeouts = typeof TIMEOUTS;

export type CaptureState = "captured" | "blocked" | "error";

export type CaptureRequest = {
  url: string;
  viewport: ViewportName;
  /** CSS selectors; see `combineMasks`. */
  masks: string[];
  /** Where the Playwright trace zip is written, whatever the outcome. */
  tracePath: string;
};

export type CaptureResult = {
  state: CaptureState;
  /** Why the capture is blocked or failed; null when captured. */
  detail: string | null;
  health: HealthSnapshot;
  /** Full-page PNG, only for `captured`. Dimensions come from the PNG itself. */
  image: { png: Uint8Array; width: number; height: number } | null;
  /** Readiness limits, unmatched masks and read-only policy aborts. */
  warnings: string[];
  /** Null only if saving the trace failed (a warning says so). */
  tracePath: string | null;
};

export type SessionOptions = {
  timeouts?: Partial<Timeouts>;
  /** Test fixtures with self-signed certificates only; never set for real sites. */
  ignoreHTTPSErrors?: boolean;
};

export type CaptureSession = {
  /** Throws `MaskSelectorError` for the first selector that is not valid CSS. */
  validateMasks(selectors: string[]): Promise<void>;
  /** One page at one viewport in a fresh context. Throws only `MaskSelectorError`. */
  capture(request: CaptureRequest): Promise<CaptureResult>;
  close(): Promise<void>;
};

/** A mask that is not valid CSS: a configuration error. */
export class MaskSelectorError extends Error {
  constructor(readonly selector: string) {
    super(`mask ${JSON.stringify(selector)} is not a valid CSS selector`);
    this.name = "MaskSelectorError";
  }
}

export const MASK_COLOR = "#FF00FF";
const FREEZE_CSS = `*, *::before, *::after {
  animation: none !important; transition: none !important; caret-color: transparent !important; scroll-behavior: auto !important;
}`;

/** Site masks then page masks, without duplicates. */
export const combineMasks = (site: Site, page: SitePage): string[] => [...new Set([...site.mask, ...page.mask])];

/**
 * Names a positively identified bot challenge or firewall interstitial, else null. Only explicit
 * markers count: pages merely mentioning Cloudflare or showing a form CAPTCHA are not challenges.
 */
export function challengeReason(headers: Record<string, string>, html: string): string | null {
  if (headers["cf-mitigated"]?.toLowerCase() === "challenge") return "Cloudflare challenge (cf-mitigated: challenge)";
  if (html.includes("_cf_chl_opt")) return "Cloudflare challenge page";
  const title = (/<title[^>]*>([^<]*)<\/title>/i.exec(html)?.[1] ?? "").trim().toLowerCase();
  if (title.startsWith("attention required!") && title.includes("cloudflare")) return "Cloudflare block page";
  if (title.includes("sucuri website firewall")) return "Sucuri firewall page";
  return null;
}

/** Launches headless Chromium. Callers must `close()` the session. */
export async function openCaptureSession(options: SessionOptions = {}): Promise<CaptureSession> {
  const browser = await chromium.launch({ headless: true });
  const timeouts = { ...TIMEOUTS, ...options.timeouts };
  const ignoreHTTPSErrors = options.ignoreHTTPSErrors ?? false;
  return {
    async validateMasks(selectors) {
      const context = await browser.newContext();
      try {
        await assertCss(await context.newPage(), selectors);
      } finally {
        await context.close();
      }
    },
    capture: (request) => capture(browser, timeouts, ignoreHTTPSErrors, request),
    close: () => browser.close(),
  };
}

async function assertCss(page: Page, selectors: string[]): Promise<void> {
  const bad = await page.evaluate((list) => {
    const probe = document.createDocumentFragment();
    return list.find((s) => {
      try {
        probe.querySelector(s);
        return false;
      } catch {
        return true;
      }
    });
  }, selectors);
  if (bad !== undefined) throw new MaskSelectorError(bad);
}

const firstLine = (e: unknown) => String(e instanceof Error ? e.message : e).split("\n")[0]!.replace(/^\w+\.\w+: /, "");

async function capture(browser: Browser, t: Timeouts, ignoreHTTPSErrors: boolean, req: CaptureRequest): Promise<CaptureResult> {
  const context = await browser.newContext({
    viewport: VIEWPORTS[req.viewport],
    deviceScaleFactor: 1,
    locale: "en-US",
    timezoneId: "UTC",
    colorScheme: "light",
    reducedMotion: "reduce",
    serviceWorkers: "block",
    ignoreHTTPSErrors,
  });
  const warnings = new Set<string>();
  const consoleErrors: string[] = [];
  const failedRequests: HealthSnapshot["failedRequests"] = [];
  const insecure = new Set<string>();
  let status: number | null = null;
  let criticalError = false;
  let result: Omit<CaptureResult, "health" | "warnings" | "tracePath">;

  await context.tracing.start({ screenshots: true, snapshots: true, sources: true });
  const page = await context.newPage();
  let traceSaved = false;
  try {
    result = await run();
  } catch (e) {
    if (e instanceof MaskSelectorError) throw e;
    result = { state: "error", detail: `capture failed: ${firstLine(e)}`, image: null };
  } finally {
    try {
      mkdirSync(dirname(req.tracePath), { recursive: true });
      await context.tracing.stop({ path: req.tracePath });
      traceSaved = true;
    } catch (e) {
      warnings.add(`trace not saved: ${firstLine(e)}`);
    }
    await context.close().catch(() => {});
  }

  const finalUrl = page.url() === "about:blank" ? req.url : page.url();
  const health = normalizeHealth({
    status,
    finalUrl,
    criticalError,
    consoleErrors,
    failedRequests,
    mixedContent: finalUrl.startsWith("https:") ? [...insecure] : [],
  });
  return { ...result, health, warnings: [...warnings], tracePath: traceSaved ? req.tracePath : null };

  async function run(): Promise<typeof result> {
    // Read-only browsing: only GET leaves the browser.
    await context.route("**/*", (route) => {
      const r = route.request();
      if (r.method() === "GET") return route.continue();
      warnings.add(`read-only policy blocked ${r.method()} ${r.url()}`);
      return route.abort("blockedbyclient");
    });
    const isMainDocument = (r: Request) => r.isNavigationRequest() && r.frame() === page.mainFrame();
    page.on("console", (msg) => {
      const text = msg.text();
      const mixed = /^Mixed Content: .*? requested an insecure [^']*'([^']+)'/s.exec(text);
      if (mixed) insecure.add(mixed[1]!);
      // Resource load errors are recorded precisely (URL and status) from network events instead.
      else if (msg.type() === "error" && !text.startsWith("Failed to load resource:")) consoleErrors.push(text);
    });
    page.on("pageerror", (e) => consoleErrors.push(`Uncaught ${e.name}: ${e.message}`));
    page.on("request", (r) => {
      if (r.url().startsWith("http:") && !isMainDocument(r)) insecure.add(r.url());
    });
    page.on("response", (r) => {
      if (r.status() >= 400 && !isMainDocument(r.request())) failedRequests.push({ url: r.url(), status: r.status() });
    });
    page.on("requestfailed", (r) => {
      // Policy aborts are warnings; ERR_ABORTED is the browser cancelling its own request (media ranges, superseded loads).
      if (r.method() !== "GET" || isMainDocument(r) || r.failure()?.errorText === "net::ERR_ABORTED") return;
      failedRequests.push({ url: r.url(), status: null });
    });

    await assertCss(page, req.masks);

    let response;
    try {
      response = await page.goto(req.url, { waitUntil: "load", timeout: t.navigation });
    } catch (e) {
      return { state: "blocked", detail: `navigation failed: ${firstLine(e)}`, image: null };
    }
    status = response?.status() ?? null;
    const html = await page.content().catch(() => "");
    criticalError = await hasCriticalError(page);
    const challenge = status === 403 ? "HTTP 403 Forbidden" : challengeReason((await response?.allHeaders()) ?? {}, html);
    if (challenge) return { state: "blocked", detail: challenge, image: null };

    await page.waitForLoadState("networkidle", { timeout: t.networkIdle }).catch(() => {
      warnings.add(`network not idle after ${t.networkIdle} ms; captured anyway`);
    });
    if (!(await scrollThrough(page, t.lazyScroll))) warnings.add(`lazy-load scrolling stopped at the ${t.lazyScroll} ms limit`);
    if (!(await settle(page, t.settle))) warnings.add(`fonts/images still loading after ${t.settle} ms; captured anyway`);
    criticalError = await hasCriticalError(page);
    for (const url of await insecureReferences(page)) insecure.add(url);

    const mask = req.masks.map((s) => page.locator(`css=${s}`));
    for (const [i, locator] of mask.entries()) {
      if ((await locator.count()) === 0) warnings.add(`mask ${JSON.stringify(req.masks[i])} matched nothing`);
    }
    const png = new Uint8Array(
      await page.screenshot({
        type: "png",
        fullPage: true,
        animations: "disabled",
        caret: "hide",
        style: FREEZE_CSS,
        mask,
        maskColor: MASK_COLOR,
        timeout: t.screenshot,
      }),
    );
    // PNG IHDR: width and height are big-endian uint32 at bytes 16 and 20.
    const ihdr = new DataView(png.buffer, png.byteOffset, png.byteLength);
    return { state: "captured", detail: null, image: { png, width: ihdr.getUint32(16), height: ihdr.getUint32(20) } };
  }
}

async function hasCriticalError(page: Page): Promise<boolean> {
  return page
    .evaluate((phrase) => (document.body?.innerText ?? "").toLowerCase().includes(phrase), CRITICAL_ERROR_PHRASE.toLowerCase())
    .catch(() => false);
}

/** Scrolls down a viewport at a time until the bottom stops moving, then back to the top. False if the limit hit first. */
async function scrollThrough(page: Page, limit: number): Promise<boolean> {
  const deadline = Date.now() + limit;
  let bottom = false;
  while (!bottom && Date.now() < deadline) {
    const before = await page.evaluate(() => {
      window.scrollBy({ top: window.innerHeight, behavior: "instant" });
      return window.scrollY;
    });
    await page.waitForTimeout(Math.max(0, Math.min(150, deadline - Date.now())));
    bottom = await page.evaluate((y) => {
      const height = (document.scrollingElement ?? document.documentElement).scrollHeight;
      return window.scrollY + window.innerHeight >= height - 1 && window.scrollY === y;
    }, before);
  }
  await page.evaluate(() => window.scrollTo({ top: 0, behavior: "instant" }));
  return bottom;
}

/** Waits for web fonts and pending images, up to `limit`. False if they had not settled. */
function settle(page: Page, limit: number): Promise<boolean> {
  return page.evaluate(
    (ms) =>
      Promise.race([
        Promise.all([
          document.fonts.ready,
          ...[...document.images]
            .filter((img) => !img.complete)
            .map((img) => new Promise((done) => ["load", "error"].forEach((ev) => img.addEventListener(ev, done, { once: true })))),
        ]).then(() => true),
        new Promise<boolean>((done) => setTimeout(() => done(false), ms)),
      ]),
    limit,
  );
}

/**
 * Absolute http: URLs in resource attributes, including ones Chromium blocks or upgrades before any
 * request is observable. Plain links are not resources. CSS url() and script-built URLs are not scanned.
 */
function insecureReferences(page: Page): Promise<string[]> {
  return page.evaluate(() => {
    const rels = ["stylesheet", "icon", "apple-touch-icon", "preload", "modulepreload", "prefetch", "manifest"];
    const sources: [string, string][] = [
      ["img, script, iframe, frame, embed, source, video, audio, track, input[type=image i]", "src"],
      ["img, source", "srcset"],
      [rels.map((r) => `link[rel~="${r}" i]`).join(", "), "href"],
      ["object", "data"],
      ["video", "poster"],
    ];
    const urls: string[] = [];
    for (const [selector, attr] of sources) {
      for (const el of document.querySelectorAll(selector)) {
        const value = el.getAttribute(attr);
        if (!value) continue;
        const refs = attr === "srcset" ? value.split(",").map((c) => c.trim().split(/\s+/)[0] ?? "") : [value];
        for (const ref of refs) {
          try {
            const url = new URL(ref, document.baseURI);
            if (url.protocol === "http:") urls.push(url.href);
          } catch {}
        }
      }
    }
    return urls;
  });
}
/** Raw health of one captured page, persisted verbatim as `<pageKey>.health.json`. */
export type HealthSnapshot = {
  /** Final main-document HTTP status, null when no response arrived. */
  status: number | null;
  finalUrl: string;
  criticalError: boolean;
  consoleErrors: string[];
  /** Subresource HTTP >= 400 responses, or `status: null` for transport failures. */
  failedRequests: { url: string; status: number | null }[];
  /** HTTP resources referenced by a final HTTPS document. */
  mixedContent: string[];
};

export type Severity = "warning" | "failure";

export type HealthFinding = {
  severity: Severity;
  kind: "status" | "critical-error" | "console-error" | "failed-request" | "mixed-content";
  detail: string;
};

export class HealthFormatError extends Error {
  constructor(field: string, detail: string) {
    super(`health: ${field}: ${detail}`);
    this.name = "HealthFormatError";
  }
}

export const CRITICAL_ERROR_PHRASE = "There has been a critical error on this website";

type FailedRequest = HealthSnapshot["failedRequests"][number];
const requestKey = (r: FailedRequest) => `${r.status ?? ""} ${r.url}`;
const sortedUnique = (xs: string[]) => [...new Set(xs)].sort();

/** Deduplicates and deterministically sorts every list, keeping query strings and statuses distinct. */
export function normalizeHealth(h: HealthSnapshot): HealthSnapshot {
  const requests = new Map(h.failedRequests.map((r) => [JSON.stringify([r.url, r.status]), { url: r.url, status: r.status }]));
  return {
    status: h.status,
    finalUrl: h.finalUrl,
    criticalError: h.criticalError,
    consoleErrors: sortedUnique(h.consoleErrors),
    failedRequests: [...requests.values()].sort((a, b) =>
      a.url < b.url ? -1 : a.url > b.url ? 1 : (a.status ?? -1) - (b.status ?? -1),
    ),
    mixedContent: sortedUnique(h.mixedContent),
  };
}

/**
 * Findings for `actual`, relative to an optional baseline. HTTP >= 400, critical errors and mixed
 * content always fail. Console errors and failed URL/status pairs already in the baseline are
 * warnings; new ones fail; ones only in the baseline are not reported.
 */
export function evaluateHealth(actual: HealthSnapshot, baseline: HealthSnapshot | null): HealthFinding[] {
  const findings: HealthFinding[] = [];
  const fail = (kind: HealthFinding["kind"], detail: string) => findings.push({ severity: "failure", kind, detail });
  const known = (seen: boolean): Severity => (seen ? "warning" : "failure");

  if (actual.status === null) fail("status", `no HTTP response for ${actual.finalUrl}`);
  else if (actual.status >= 400) fail("status", `HTTP ${actual.status} for ${actual.finalUrl}`);
  if (actual.criticalError) fail("critical-error", `page shows "${CRITICAL_ERROR_PHRASE}"`);
  for (const url of sortedUnique(actual.mixedContent)) fail("mixed-content", `insecure resource ${url}`);

  const oldConsole = new Set(baseline?.consoleErrors);
  for (const message of sortedUnique(actual.consoleErrors)) {
    findings.push({ severity: known(oldConsole.has(message)), kind: "console-error", detail: message });
  }
  const oldRequests = new Set(baseline?.failedRequests.map(requestKey));
  for (const r of normalizeHealth(actual).failedRequests) {
    const what = r.status === null ? "transport failure" : `HTTP ${r.status}`;
    findings.push({ severity: known(oldRequests.has(requestKey(r))), kind: "failed-request", detail: `${what} ${r.url}` });
  }
  return findings;
}

/** Validates parsed `.health.json` content; throws `HealthFormatError` naming the bad field. */
export function parseHealth(value: unknown): HealthSnapshot {
  const isObj = (v: unknown): v is Record<string, unknown> => typeof v === "object" && v !== null && !Array.isArray(v);
  const isStatus = (v: unknown) => v === null || Number.isInteger(v);
  const strings = (v: unknown) => Array.isArray(v) && v.every((s) => typeof s === "string");
  if (!isObj(value)) throw new HealthFormatError("<root>", "must be an object");

  const keys = ["status", "finalUrl", "criticalError", "consoleErrors", "failedRequests", "mixedContent"];
  for (const key of Object.keys(value)) if (!keys.includes(key)) throw new HealthFormatError(key, "unknown key");
  const { status, finalUrl, criticalError, consoleErrors, failedRequests, mixedContent } = value;
  if (!isStatus(status)) throw new HealthFormatError("status", "must be an integer or null");
  if (typeof finalUrl !== "string") throw new HealthFormatError("finalUrl", "must be a string");
  if (typeof criticalError !== "boolean") throw new HealthFormatError("criticalError", "must be a boolean");
  if (!strings(consoleErrors)) throw new HealthFormatError("consoleErrors", "must be a list of strings");
  const requestOk = (r: unknown) => isObj(r) && Object.keys(r).length === 2 && typeof r.url === "string" && isStatus(r.status);
  if (!Array.isArray(failedRequests) || !failedRequests.every(requestOk)) {
    throw new HealthFormatError("failedRequests", "must be a list of {url, status}");
  }
  if (!strings(mixedContent)) throw new HealthFormatError("mixedContent", "must be a list of strings");
  return normalizeHealth(value as HealthSnapshot);
}
import pixelmatch from "pixelmatch";
import { PNG } from "pngjs";

export type Dimensions = { width: number; height: number };

export type Comparison =
  | {
      state: "same" | "changed";
      baseline: Dimensions;
      actual: Dimensions;
      /** Any width or height difference; always `changed`, and pixel counts are then null. */
      dimensionsChanged: boolean;
      diffPixels: number | null;
      /** `diffPixels / (width * height)`; changed iff it exceeds `allowance`. */
      ratio: number | null;
      allowance: number;
      /** Diff PNG; for dimension changes, both images padded to a common canvas first. */
      diffPng: Uint8Array;
    }
  | { state: "error"; detail: string };

// Stable, explicit pixelmatch settings (threshold 0.1 is locked; the rest are pixelmatch defaults).
const MATCH = {
  threshold: 0.1,
  includeAA: false,
  alpha: 0.1,
  aaColor: [255, 255, 0],
  diffColor: [255, 0, 0],
  diffMask: false,
} satisfies Parameters<typeof pixelmatch>[5];

// Magenta marks canvas area outside one image when dimensions differ.
const PAD: [number, number, number, number] = [255, 0, 255, 255];

export function comparePng(baselinePng: Uint8Array, actualPng: Uint8Array, allowance: number): Comparison {
  let base: PNG, actual: PNG;
  try {
    base = PNG.sync.read(Buffer.from(baselinePng));
  } catch (e) {
    return { state: "error", detail: `baseline PNG could not be decoded: ${(e as Error).message}` };
  }
  try {
    actual = PNG.sync.read(Buffer.from(actualPng));
  } catch (e) {
    return { state: "error", detail: `actual PNG could not be decoded: ${(e as Error).message}` };
  }

  const dims = { baseline: { width: base.width, height: base.height }, actual: { width: actual.width, height: actual.height } };
  if (base.width !== actual.width || base.height !== actual.height) {
    const width = Math.max(base.width, actual.width);
    const height = Math.max(base.height, actual.height);
    const a = pad(base, width, height);
    const b = pad(actual, width, height);
    const diff = new PNG({ width, height });
    pixelmatch(a.data, b.data, diff.data, width, height, MATCH);
    return { state: "changed", ...dims, dimensionsChanged: true, diffPixels: null, ratio: null, allowance, diffPng: encode(diff) };
  }

  const { width, height } = base;
  const diff = new PNG({ width, height });
  const diffPixels = pixelmatch(base.data, actual.data, diff.data, width, height, MATCH);
  const ratio = diffPixels / (width * height);
  const state = ratio > allowance ? "changed" : "same";
  return { state, ...dims, dimensionsChanged: false, diffPixels, ratio, allowance, diffPng: encode(diff) };
}

function pad(img: PNG, width: number, height: number): PNG {
  const out = new PNG({ width, height });
  for (let i = 0; i < width * height; i++) out.data.set(PAD, i * 4);
  PNG.bitblt(img, out, 0, 0, img.width, img.height, 0, 0);
  return out;
}

const encode = (img: PNG) => new Uint8Array(PNG.sync.write(img));
import type { CaptureState, ViewportName } from "../capture.ts";
import type { Dimensions } from "../compare.ts";
import type { HealthFinding } from "../health.ts";

/** Filled by the form-check leaf; rendered as a Forms column when any page has it. */
export type FormResult = {
  selector: string;
  plugin: "gravity" | "fluent" | "unknown";
  outcome: "delivered" | "delivered-spam" | "not-verified" | "rejected" | "unsupported" | "failed";
  detail: string;
